export type DocumentsCancelInput = {
  id: string;
  reason?: string | null;
};

export type AttachmentRequest = {
  contentType?: string | null;
  description: string;
  fileId?: string | null;
  fileName?: string | null;
  id: string;
  /** `file` for an upload the sender asked for, `photo` for a live photo taken with the camera while signing. */
  kind: string;
  name: string;
  partyId: string;
  required: boolean;
  sha256?: string | null;
  sizeBytes?: number | null;
  uploadedAt?: string | null;
};

/** One rule of when a field is shown. A field with several rules shows only when all hold. */
export type Condition = {
  /** The label of the field the rule looks at. */
  field: string;
  op: ConditionOp;
  /** What to compare with: an option, a number, a date as YYYY-MM-DD or text. Not used by `filled` and `empty`. */
  value?: string | null;
};

export type ConditionOp = "equals" | "not_equals" | "empty" | "greater" | "less" | "filled" | "contains";

export type FieldRow = {
  /** The field is shown only when all of these hold. */
  conditions: Array<Condition>;
  /** How a date or number is written on the page. */
  format?: string | null;
  /** For a formula field, the expression it computes. */
  formula?: string | null;
  /** Radio buttons with the same key form one group. */
  groupKey?: string | null;
  height: number;
  id: string;
  kind: string;
  label: string;
  /** The choices of a list field, or the one option of a radio button. */
  options: Array<string>;
  page: number;
  partyId?: string | null;
  /** The signer sees the value but cannot change it. */
  readOnly: boolean;
  required: boolean;
  validation: Validation;
  /** The value; for image and file fields, the name of the upload. */
  value?: string | null;
  width: number;
  x: number;
  y: number;
};

export type FileRecord = {
  contentType: string;
  createdAt: string;
  id: string;
  kind: string;
  name: string;
  sha256: string;
  sizeBytes: number;
};

/** A party as senders see it. The personal number is shown masked. */
export type PartyView = {
  authToSign: string;
  authToView: string;
  company?: string | null;
  declineReason?: string | null;
  declinedAt?: string | null;
  delivery: string;
  email?: string | null;
  id: string;
  /** What this party reads, if not the document's language. */
  language?: string | null;
  name: string;
  notifiedAt?: string | null;
  personalNumber?: string | null;
  phone?: string | null;
  role: string;
  signOrder: number;
  signedAt?: string | null;
  status: string;
  viewedAt?: string | null;
  /** The party must take a live webcam photo before signing. */
  webcamPhoto: boolean;
};

/** Checks on what a signer types. Each applies only to the kinds it makes sense for. */
export type Validation = {
  /** Largest number for a number field, or latest date as YYYY-MM-DD for a date picker. */
  max?: string | null;
  /** Most characters (text, initials and company fields). */
  maxLength?: number | null;
  /** Shown to the signer instead of the built-in error when any check fails. */
  message?: string | null;
  /** Smallest number for a number field, or earliest date as YYYY-MM-DD for a date picker. */
  min?: string | null;
  /** Fewest characters (text, initials and company fields). */
  minLength?: number | null;
  /** A regular expression the whole value must match (text, initials and company fields), such as `[0-9]{3} ?[0-9]{2}` for a Swedish postcode. */
  pattern?: string | null;
};

export type DocumentsCancelOutput = DocumentView;

export type DocumentView = {
  /** Archived documents and templates are left out of lists unless asked for; archived templates cannot be used. */
  archivedAt?: string | null;
  /** Files parties are asked to upload while signing, and what they uploaded. */
  attachments: Array<AttachmentRequest>;
  canEdit: boolean;
  canceledAt?: string | null;
  completedAt?: string | null;
  createdAt: string;
  /** When the retention rules will delete this document, if any rule applies to it. */
  deletesAt?: string | null;
  expiresAt?: string | null;
  externalId?: string | null;
  fields: Array<FieldRow>;
  files: Array<FileRecord>;
  folderId?: string | null;
  id: string;
  isTemplate: boolean;
  language: string;
  /** On legal hold: no retention rule or person can delete it until the hold is released. */
  legalHold: boolean;
  legalHoldAt?: string | null;
  legalHoldReason?: string | null;
  message: string;
  metadata: unknown;
  originalSha256?: string | null;
  ownerId?: string | null;
  ownerName?: string | null;
  pageCount?: number | null;
  parties: Array<PartyView>;
  reminderDays?: number | null;
  /** Signers may share a read-only copy with their own AI agent. */
  reviewLinks: boolean;
  sealedSha256?: string | null;
  /** Whether the seal carries a time stamp from the time stamp authority; unset until sealed. */
  sealedWithTimestamp?: boolean | null;
  sentAt?: string | null;
  sequential: boolean;
  status: string;
  templateId?: string | null;
  /** The title of the template this document was made from, if you can see it. */
  templateTitle?: string | null;
  /** The version of the template this document was made from. */
  templateVersion?: number | null;
  title: string;
  updatedAt: string;
};

