export type AttachmentRequestInput = {
  /** Shown to the party under the name. */
  description?: string;
  /** What to upload, e.g. "Copy of your ID". */
  name: string;
  /** The party cannot sign without it. Defaults to true. */
  required?: boolean | null;
};

/** How the party gets their link. `link` hands it to the sender (or the calling system) instead; `in_person` means the party signs on the sender's own device, started from the document page. */
export type Delivery = "email" | "sms" | "link" | "in_person" | "none";

export type PartyInput = {
  /** Files the party must or may upload while signing, such as a copy of an ID. Leave out to keep the current ones. */
  attachments?: Array<AttachmentRequestInput> | null;
  authToSign?: AuthMethod;
  authToView?: AuthMethod;
  company?: string | null;
  delivery?: Delivery;
  email?: string | null;
  /** Keep an existing party (and its fields) by passing its id. */
  id?: string | null;
  /** The language of this party's emails, SMS and signing page, if not the document's: en, zh, hi, es, fr, ar, bn, pt, ru, ur or sv. Leave out to use the document's. */
  language?: string | null;
  name: string;
  /** A national id number to match against the eID result, e.g. a Swedish personnummer. Stored encrypted. Leave it out (or send the masked value) to keep the stored one; send "" to remove it. */
  personalNumber?: string | null;
  /** With country code, e.g. +46701234567. Needed for SMS delivery and SMS codes. */
  phone?: string | null;
  role?: PartyRole;
  /** In sequential documents, lower numbers sign first. Equal numbers sign in parallel. */
  signOrder?: number | null;
  /** Ask the party to take a live photo of themselves with their webcam or phone camera before they can sign. The photo is stored encrypted, shown to the sender and sealed into the evidence. Leave out to keep the current setting. */
  webcamPhoto?: boolean | null;
};

/** Signers sign, approvers approve without a signature image, viewers receive the signed copy. */
export type PartyRole = "signer" | "approver" | "viewer";

